{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — are we maximizing total profit (unit price minus raw material cost, minus the operating costs of the equipment used), or is there a different goal such as maximizing total output or minimizing cost?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The \"Operating Costs at Full Capacity\" column gives a cost for each piece of equipment — is this a fixed cost incurred whenever that equipment is used at all (regardless of how many hours), or is it a cost that scales proportionally with the fraction of its effective hours actually used?"
  ],
  "rationale": "The response asks for a single policy choice regarding the nature of the operating costs (fixed vs. variable), which constitutes one semantically independent question."
}

{
  "action": "question",
